style.css:
@-moz-document domain("juejin.cn") {
/* Juejin ships NO native dark mode. The UI is a server-rendered Vue SPA with
     stable BEM-ish class names; most text is colored through a DESIGN-TOKEN gray
     font scale (`--juejin-font-1` #252933 primary … `--juejin-font-2` #515767
     secondary … `--juejin-font-3` #8a919f … `--juejin-font-4` #c2c8d1) plus some
     hardcoded literals, on white #fff surfaces over a #f2f3f5 page, with a
     github-light highlight.js code theme. This theme rebuilds the palette: a
     GitHub-dark-ish surface stack, softened borders, a full dark syntax palette
     for code, the brand blue refined for dark, and — critically — a full
     dark→light REMAP of the gray font scale so every secondary/muted text reads. */

  :root {
    color-scheme: dark;
  }

  /* ---------- Gray font-scale remap (the #1 dark-on-dark fix) ----------
     Juejin defines its font tokens on `body` (NOT :root), and colors nearly all
     secondary/muted text through them. We MUST redefine the whole scale dark→light
     at the same-or-deeper scope so it wins: primary text light, the muted ends
     lifted to legible greys. This also fixes inline `color: var(--juejin-font-*)`
     used by pin topic hashtags. Defined on :root, html AND body for full coverage. */
  :root,
  html,
  body {
    --juejin-font-1: #e6edf3 !important;   /* was #252933 — primary text */
    --juejin-font-2: #c4cdd6 !important;   /* was #515767 — secondary text */
    --juejin-font-3: #9aa6b0 !important;   /* was #8a919f — tertiary/muted */
    --juejin-font-4: #8b949e !important;   /* was #c2c8d1 — faint/disabled */
    --juejin-ai-text-desc: #9aa6b0 !important; /* was #9299a7 */
    --juejin-font-danger: #ff5e5e !important;
    --juejin-font-success: #3fb950 !important;
    --juejin-font-warning: #ffa657 !important;
    --juejin-font-white: #e6edf3 !important;
    --juejin-font-brand1-normal: #5fb0e6 !important; /* topic/link accent */
    --juejin-font-brand-normal: #5fb0e6 !important;
    --juejin-brand-normal: #1e80ff !important;
    --juejin-brand-1-normal: #5fb0e6 !important;

    /* ---------- Surface tokens for floating panels ----------
       `--juejin-popup` (#fff) paints EVERY floating panel: the feed-card dislike
       flyout, the author hover-card, the search suggest list, the nav category
       popover, byte-design modals/tooltips, and the caret triangles drawn from it
       as a border-color. Each of those panels only enters the DOM on hover/click,
       so a load-time scan reports zero nodes and they shipped white. Remap the
       token once — it reaches the panels we cannot open while logged out. The two
       grays are background/border-only (never a text colour), so darkening them is
       safe: `-2` fills chips and control borders, `-3` is the hover-row highlight. */
    --juejin-popup: #1c2128 !important;    /* was #fff  — floating panel surface */
    --juejin-gray-2: #21262d !important;   /* was #f2f3f5 — chip / control fill */
    --juejin-gray-3: #262c33 !important;   /* was #f7f8fa — hover-row highlight */

    /* `--juejin-navigation` (#fff) is the header's own surface token. We repaint
       `.main-header` directly, so on desktop the token never shows — but below
       ~960px juejin reflows the nav and `li.main-nav-list` becomes an absolutely
       positioned block painted FROM THE TOKEN, so a 68×52 pure-white slab landed
       behind the active nav label. Desktop-only review never sees it. */
    --juejin-navigation: #0d1117 !important; /* was #fff — header surface */
  }

  /* ---------- Base ---------- */
  html,
  body,
  #juejin,
  .view-container,
  .main-container,
  .container,
  .global-layout,
  .root-view-bg {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  body {
    scrollbar-color: #3a424d #14181d;
  }

  /* Soften every default light border into a subtle dark line */
  * {
    border-color: #262c33 !important;
  }

  /* …but that reset also repaints the two places a border is not a border:
     (a) CSS-triangle carets built from transparent side borders — the search
         filter caret rendered as a solid grey RECTANGLE instead of a ▼;
     (b) the `.login-popover` 20px transparent top border used as a hover-bridge
         spacer, which became an opaque grey band above the popover;
     (c) the booklet tab's 2px brand-blue active underline, flattened to the
         border tone and thus invisible.
     Restore each explicitly. (`*` matches elements only — pseudo-element
     triangles are unaffected.) */
  .dropdown-toggle .icon,
  .drop-down .icon {
    border-top-color: #8b949e !important;
    border-left-color: transparent !important;
    border-right-color: transparent !important;
  }

  .login-popover {
    border-top-color: transparent !important;
  }

  .book-menu .item.active {
    border-bottom-color: #1e80ff !important;
  }

  /* Row dividers in the article-page recommended lists ("为你推荐"/"相关推荐")
     are drawn as a 1px `.content-wrapper::before` with a hardcoded light bg
     (#e4e6eb) — NOT a border, so the `*` border rule above can't reach it and
     it renders as a bright line on dark. Darken the pseudo to the border tone. */
  .entry-list .content-wrapper::before,
  .entry .content-wrapper::before,
  .follow-block::after,
  .follow-block::before {
    background-color: #262c33 !important;
  }

  /* Standalone `.divider` hairlines (creator-center dropdown, sidebar rank cards,
     course filter header) are 1px DIVs painting a hardcoded #e4e6eb — a bright
     white rule across the dark panel. At 1px tall they slip every audit height
     filter. The nested `.divider > .content` carries a 50%-alpha variant. */
  .divider,
  .divider .content,
  .course-header::after {
    background-color: #262c33 !important;
  }

  /* Wrappers that only carry a white bg → neutralize, so the surfaces below
     (cards/header) define the real elevation. Keeps things from going flat. */
  .view-container,
  .main-container,
  .main-content,
  .container,
  .global-layout,
  .layout-content,
  .view,
  .index-view,
  .article-view,
  .pin-view,
  .search-view,
  .main-list,
  .search-list,
  .result-list {
    background-color: transparent !important;
  }

  /* Search results sub-nav bar (filter tabs) → elevated dark surface */
  .view-nav,
  .search-nav,
  .filter-nav {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
  }

  /* Tag detail page (juejin.cn/tag/<name>): the header `.tag-info-box` ships a
     hardcoded light-grey (#f8f9fa) banner carrying the tag name + follow/article
     counts — a bright strip with washed light-on-light text. Its wrapper `.tag-view`
     only carries the white bg. Neutralize the wrapper, dark the header banner and
     force its title/counts light so they read. */
  .tag-view,
  .tag-detail-view {
    background-color: transparent !important;
  }

  .tag-info-box {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
  }

  .tag-info-box .tag-title,
  .tag-info-box .title,
  .tag-info-box .tag-name,
  .tag-info-box .count,
  .tag-info-box .tag-stat,
  .tag-info-box .stat {
    color: #e6edf3 !important;
  }

  /* Tag header follow/count-meta: `.tag-meta` (关注/文章 counts) hardcodes #666 —
     dark-on-dark once the banner is darked → lift to readable grey. The `.subscribe-btn`
     ("关注") is a 60×32 white pill with brand-green text that slips under the audit
     size filter; dark the fill, keep the green label + a green outline so it still
     reads as the follow CTA. */
  .tag-info-box .tag-meta,
  .tag-meta {
    color: #8b949e !important;
  }

  .subscribe-btn {
    background-color: #1c2128 !important;
    border-color: #37c700 !important;
  }

  /* Brand-tinted GHOST buttons: rgba(30,128,255,.05) fill, rgba(30,128,255,.3)
     outline, #1e80ff label. Two of them shipped flat grey — the sidebar "去签到"
     lost its outline to the `*` border reset, and the author hover-card's "私信"
     lost both outline and label, so it read as a disabled control next to the blue
     "关注". Neither is a filled CTA, so they keep the tint + accent label. */
  .signin-tip .btn.signin-btn,
  .btn.signin-btn {
    border-color: rgba(30, 128, 255, 0.35) !important;
  }

  /* The hover card renders INSIDE the feed row, so `.entry-footer *` (0,1,0) also
     claims the "私信" label — a bare `.im-button *` only ties it and loses on order. */
  .im-button,
  .im-button.im-btn,
  .im-button.im-btn *,
  .operate-btn .im-button,
  .operate-btn .im-button * {
    border-color: rgba(30, 128, 255, 0.35) !important;
    color: #5fb0e6 !important;
  }

  /* The pin sidebar's logged-out "登录 / 注册" is a brand-blue link, not a name —
     our `.user-name, .username` remap greyed it into the "即刻玩转沸点" subtitle. */
  p.username.nouser,
  .username.nouser {
    color: #5fb0e6 !important;
  }

  /* Hot-ranking page (juejin.cn/hot/articles → 掘金热榜): the whole tree lives in a
     `.hot-lists` / `.hot-list-wrap` / `.hot-list-body` namespace with white
     container bgs, a white `.hot-side-nav` category sidebar, and a decorative
     `.hot-top-bg` banner whose bg-image is a white→blue gradient. Wrappers →
     transparent; the sidebar → elevated dark; the banner gradient remapped to a
     subtle dark blue glow (the list rows already ride the card + font-scale rules). */
  .hot-lists,
  .hot-list-wrap,
  .hot-list-body,
  .hot-list-view {
    background-color: transparent !important;
  }

  .hot-side-nav,
  .hot-nav,
  .hot-rank-nav {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
  }

  .hot-top-bg {
    background-image: linear-gradient(0deg, #14181d 20%, rgba(30, 128, 255, 0.15)) !important;
  }

  /* ---------- Courses / 掘金小册 (booklet) section ----------
     The 课程 area lives in its own `.course-*` / `.common-nav-header` /
     `.section` namespace untouched by the generic card rules below, and ships
     white surfaces (filter bar, content header, the whole right aside of promo
     cards). Wrappers → transparent; the filter bar, content header and aside
     panels → elevated dark. Their text already rides the remapped font scale. */
  .courses-home-view,
  .course-layout,
  .course-content-wrap,
  .course-content,
  .books-view {
    background-color: transparent !important;
  }

  .common-nav-header,
  .course-header,
  .books-filter-header,
  .course-aside .section,
  .course-aside .recommend-box,
  .course-aside .announcement,
  .course-aside .help {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
  }

  /* Booklet DETAIL page (juejin.cn/book/<id>) is a separate namespace the course
     rules never reached: `.book-card-header` (cover + buy box), the `.book-card`
     body holding the 介绍/目录 tabs and the whole chapter description, and the
     `.books-recommend` aside all ship a plain white bg. With our lightened text on
     top the entire page read white-on-white. The `.book-menu::after` tab underline
     is a light hairline. */
  .book-card,
  .book-card-header,
  .book-menu-wrap,
  .books-recommend,
  .book-catalog,
  .book-intro {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
  }

  .book-menu::after {
    background-color: #262c33 !important;
  }

  /* ---------- Header / nav (opaque, sits above scrolling content) ---------- */
  .main-header,
  .main-header-box,
  header.main-header {
    background-color: #0d1117 !important;
    border-bottom: 1px solid #262c33 !important;
    box-shadow: none !important;
  }

  /* The wordmark is an <img> SVG whose 稀土掘金 glyph paths are `fill="#323232"`
     (only the chevron mark is brand #1E80FF). On the dark header that is 1.48:1 —
     the site's own name is effectively invisible, on every page. It's a raster-ish
     <img>, so its paths cannot be restyled; the standard dark-mode filter pair
     lifts the grey glyphs to #cdcdcd (11.9:1) while hue-rotate carries the chevron
     back to (52,150,255), within a hair of the brand blue. Measured, not guessed. */
  .main-header .logo-img,
  .logo .logo-img,
  img.logo-img {
    filter: invert(1) hue-rotate(180deg);
  }

  .main-header .nav-item,
  .main-header a,
  .nav-list a,
  .nav-item-normal {
    color: #c4cdd6 !important;
  }

  .main-header .nav-item:hover,
  .main-header a:hover,
  .nav-item.active,
  .nav-item-active,
  .nav-list a:hover {
    color: #e6edf3 !important;
  }

  /* The CURRENT section / sort tab. Juejin marks it `.active` (+ vue-router's
     `.route-active` / `.router-link-exact-active`) and colours the anchor #1e80ff:
     the main header (课程 on /course, 沸点 on /pins), the search type nav
     (综合/文章/…), the search sort nav (综合排序/…), and the tag page's 热门/最新/最热.
     Our own `a`, `.nav-list a` and `.list-header .nav-item` rules repainted that
     anchor the same grey as its inactive siblings, so no page showed which tab was
     selected. The `li` guard matters: the user-profile tab bar uses `div.nav-item`
     and marks its active tab with primary text (#252933 natively), not the accent —
     it must keep the white `.item-title` treatment below. */
  li.nav-item.active,
  li.nav-item.route-active,
  li.nav-item.router-link-exact-active,
  li.nav-item.active > a,
  li.nav-item.route-active > a,
  li.nav-item.router-link-exact-active > a {
    color: #5fb0e6 !important;
  }

  /* Left category rail: the selected row keeps its blue-tinted `.active-nav` fill,
     but our blanket `.nav-item-text` literal remap greyed the label that native
     paints #1e80ff — the tint alone read as a hover, not a selection. The 热榜 page's
     SUB-category rail (综合/后端/前端…) marks the selected row with `.active-sub-nav` /
     `.router-link-exact-active` on a `.sub-nav-item` (NOT `.active-nav`), so the
     generic `.nav-item-text` grey won there and the current category read identical
     to its siblings — no selection indicator. Restore the accent for that state too. */
  .nav-item-content.active-nav .nav-item-text,
  .active-nav .nav-item-text,
  .sub-nav-item.active-sub-nav .nav-item-text,
  .sub-nav-item.router-link-exact-active .nav-item-text,
  .active-sub-nav .nav-item-text {
    color: #5fb0e6 !important;
  }

  /* The header "HOT" activity badge (`span.new-font`, 23×11px, one per page).
     Two of our own rules broke it: `.nav-item.link-item span` painted its label
     #c4cdd6 (2.26:1 on the #f64242 pill) and the `*` border reset repainted the
     1px ring that natively matches the header. Restore the white label, deepen the
     fill to juejin's OWN `--juejin-danger-2-deep` (#c62633 → 5.64:1 white, same hue
     family, exactly the move the brand blue makes below), and point the ring at the
     dark header so it cuts out the way #fff did on the light one. */
  .main-header .nav-item.link-item span.new-font,
  span.new-font,
  .new-font {
    background-color: #c62633 !important;
    border-color: #0d1117 !important;
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }

  /* Global search box in the header */
  .search-form,
  .search-box,
  .search-input-wrapper {
    background-color: #1c2128 !important;
    border: 1px solid #2d333b !important;
  }

  .search-input,
  input.search-input {
    background-color: transparent !important;
    color: #e6edf3 !important;
  }

  /* Header search magnifier button (Juejin's class is the typo `seach-icon-…`).
     Its `.active` state — set while the search box is focused — paints a hardcoded
     light-blue #eaf2ff fill, a bright button on the dark bar. Remap to a subtle
     brand-tinted dark so the blue magnifier icon still reads as a pressable. */
  .seach-icon-container,
  .seach-icon-container.active,
  .search-icon-btn,
  .search-btn {
    background-color: #1a2433 !important;
  }

  /* ---------- Elevated surfaces (cards, panels, sidebar blocks) ---------- */
  .entry-list-container,
  .entry-list,
  .entry,
  .item,
  .article-item,
  .index-nav,
  .nav-list-box,
  .sidebar-block,
  .signin-tip,
  .hot-list-item,
  .hot-list,
  .list_box,
  .hot_list,
  .hot_item,
  .hot-theme,
  .global-component-box,
  .recommended-area,
  .author-block,
  .side-info,
  .popular-box,
  .recommended-tags,
  .tag-list-box,
  .card,
  .block,
  .panel,
  .pin-list,
  .pin-item,
  .pin,
  .comment-list,
  .comment-item,
  .reply-list,
  .post-list-box,
  .collection-list-box,
  .collection-list,
  .like-list-box,
  .concern-list-box,
  .dropdown-list,
  .byte-popover,
  .byte-select-dropdown,
  .pop-list,
  .more-menu,
  .more-dropdown-list,
  .user-popover,
  .auth-modal,
  .auth-form,
  .modal-box,
  .column-container,
  .article-end,
  .jj-comment-list-container,
  .comment-box-common,
  .article-catalog,
  .catalog-block,
  .recommended-list-title-wrapper,
  .dock-nav,
  .userbox,
  .pin-editor,
  .pin-editor-dialog,
  .guide-link,
  .link-box,
  .activity-item,
  .activity-item.shadow,
  .badge-wall,
  .jj-recommend-users-card,
  .jj-recommend-users,
  .bottom-login-guide,
  .top-login-guide,
  .team-info,
  .more-list,
  .typehead,
  .new-topic-picker,
  .search-list-box,
  .search-suggest-list {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
    box-shadow: none !important;
  }

  /* `.author-info-block` is the article-page BYLINE ROW (author · date · views),
     not a card — it is transparent on the live site. Painting it as an elevated
     surface drew a stray grey band across the article header. */
  .author-info-block {
    background-color: transparent !important;
  }

  /* Profile list sort pills ("最新"/"热门") ship a light-grey #f2f3f5 fill, and the
     selected one a light-blue #eaf2ff — 52×28 chips that slip the audit's size
     filter and glare as pale pills on the dark list. The follow pill on the
     关注 tab (`.jj-follow-btn`) is a white 90×30 button with green text. */
  .sort-action {
    background-color: #21262d !important;
    color: #9aa6b0 !important;
  }

  .sort-action.active {
    background-color: #1a2433 !important;
    color: #5fb0e6 !important;
  }

  .jj-follow-btn {
    background-color: #1c2128 !important;
    border-color: #37c700 !important;
  }

  /* Avatar wells (`.jj-avatar`) keep a hardcoded #f9f9f9 disc behind the picture —
     a bright circle while the image lazy-loads or when the user has none. */
  .avatar.jj-avatar,
  .jj-avatar {
    background-color: #1c2128 !important;
  }

  /* Booklet cover wells on 课程 hold a light rgba(228,230,235,.5) placeholder. */
  .book-thumb,
  .book-poster {
    background-color: #1c2128 !important;
  }

  /* User-profile content column (juejin.cn/user/<id>): the activity/post feed,
     its tab bar and the badge-wall are NOT in the generic card list above and
     ship a white bg with hardcoded dark text (#333 / #1d2129). Dark the surfaces
     and force their text light so the font-scale title remap reads correctly. */
  .list-header,
  .list-header .header-content {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
  }

  .list-header .nav-item .item-title,
  .list-header .nav-item {
    color: #8b949e !important;
  }

  /* The profile tab-bar search affordance fades the scrolling tab list into the
     search icon with a hardcoded WHITE `background-image` mask
     (linear-gradient(90deg, transparent, #fff, #fff)) — bg-color transparent, and
     at 46×18px it sits under the audit's size threshold, so it paints a bright
     white strip behind the magnifier on dark. Remap the fade to the tab surface. */
  .search-icon-container {
    background-image: linear-gradient(90deg, rgba(28, 33, 40, 0), #1c2128, #1c2128) !important;
  }

  .list-header .nav-item.active .item-title,
  .list-header .nav-item.route-active .item-title,
  .list-header .nav-item.router-link-exact-active .item-title {
    color: #e6edf3 !important;
  }

  /* Post rows in the activity feed carry hardcoded literals (#171a1c title,
     #333/#909090 links, #5c6066 excerpt). The bare <h3> title is caught by the
     global heading rule; the rest are remapped here. */
  .activity-item .post-item-title,
  .activity-item .post-link,
  .activity-item h3,
  .activity-item .title,
  .activity-item .content-title {
    color: #e6edf3 !important;
  }

  .activity-item,
  .activity-item .post-item,
  .activity-item .post-item-content,
  .activity-item .post-item-excerpt,
  .activity-item .rich-content,
  .activity-item .content,
  .activity-item .abstract,
  .activity-item p {
    color: #c4cdd6 !important;
  }

  /* Badge-wall ("获得徽章 19") — count label readable on the dark surface */
  .badge-wall .badge-count {
    color: #c4cdd6 !important;
  }

  /* Profile-sidebar "team" card (juejin.cn/user/<id> → 掘金运营团队) names its
     team with a hardcoded black, invisible once we dark the card. Force light. */
  .team-info,
  .team-info .content,
  .team-info .name,
  .team-info .title {
    color: #e6edf3 !important;
  }

  /* Inset / nested light-grey areas (comment input wells, login guides,
     pin masks) — slightly darker than the card they sit in */
  .input-box,
  .comment-login-guide,
  .pin-editor .editor-body .content,
  .editor-body .content,
  .mask {
    background-color: #14181d !important;
  }

  /* Feed/detail pin bodies are an INLINE `span.content` — giving them the inset
     darker bg above made it hug each text line, painting stray highlight boxes on
     the card. Pin text should sit flat on the card like comments do. */
  .pin-view .content,
  .pin-item .content,
  .pin-list .content {
    background-color: transparent !important;
  }

  /* Blank ad slots keep a white bg — dark them so they don't flash white */
  .ad-container,
  .ad-block,
  .advert {
    background-color: #14181d !important;
  }

  /* Feed article cover thumbnails are `img.lazy.thumb` carrying a hardcoded white
     `background-color` placeholder that juejin shows behind the picture while it
     lazy-loads (and keeps if the image is broken/absent). On the dark feed every
     loading/failed cover glares as a bright white box (audit-blind — the scan
     skips <img> tags). object-fit:cover fully covers the bg once loaded, so
     darkening the placeholder is invisible for loaded covers and kills the flash. */
  img.lazy,
  img.thumb,
  img.lazy.thumb,
  .thumb-box img,
  .cover img,
  .thumb-container {
    background-color: #1c2128 !important;
  }

  /* Light-blue active tints (selected nav items, login wrap, dock tabs) */
  .nav-item-content.active-nav,
