  .author-tag,
  .achievements .name,
  .achievement-item .name {
    background-color: #1a2433 !important;
    border-color: #24314a !important;
    color: #5fb0e6 !important;
  }

  /* Hot / 热 rank markers — keep the warm accent, refined */
  .hot-number,
  .rank-number.top,
  .rank-1,
  .rank-2,
  .rank-3,
  .is-hot {
    color: #ff7043 !important;
  }

  /* Like / collect (收藏) active accents preserved */
  .like.active,
  .liked,
  .collect.active,
  .action.active {
    color: #ff5e5e !important;
  }

  /* ---------- Scrollbar ---------- */
  ::-webkit-scrollbar {
    width: 10px;
    height: 10px;
  }

  ::-webkit-scrollbar-track {
    background: #14181d;
  }

  ::-webkit-scrollbar-thumb {
    background: #3a424d;
    border-radius: 5px;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: #4a525d;
  }

  /* ---------- Interaction-only floating surfaces ----------
     These panels are `display:none` until hovered/clicked, so a static scan never
     sees them. Each keeps a white background and NO `color` of its own, so with
     `color-scheme: dark` the initial text colour is now WHITE — the labels render
     white-on-white and vanish. (Verified: the share flyout and the pin "屏蔽作者/举报"
     menu.) Dark the panel AND state the text colour explicitly. */
  .share-popup,
  .share-panel,
  .wechat-qrcode,
  .dislike-list,
  .dislike-entry,
  .action-box-wrap,
  .action-box,
  .action-bar,
  .carousel-body,
  .navigation.navigator,
  .dislike-entry .icon {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
  }

  .share-popup,
  .share-popup span,
  .share-panel,
  .share-panel span,
  .wechat-qrcode,
  .wechat-qrcode span,
  .dislike-list,
  .dislike-list span,
  .dislike-list .item,
  .action-box,
  .action-box span,
  .action-bar,
  .action-bar span,
  .navigation.navigator span {
    color: #c4cdd6 !important;
  }

  /* The feed card's "…" (dislike) flyout. It is NOT `.dislike-list`/`.dislike-entry`
     — juejin renders `.dislike-menu`, which replaces a Vue comment placeholder only
     AFTER the trigger is clicked, so `querySelectorAll('.dislike-menu')` returns 0 at
     rest and the panel evades every load-time scan. It painted `var(--juejin-popup)`
     white, and its `.menu-text` lost to our own `.entry-footer *` rule (#8b949e),
     giving a 2.9:1 grey label on a white pill over the dark feed. The token remap
     above darkens the panel; these rules restore the label/icon hierarchy (native:
     icon dimmer than label) and beat `.entry-footer *` on specificity. */
  .dislike-menu {
    background-color: #1c2128 !important;
    border: 1px solid #2d333b !important;
    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.4) !important;
  }

  .dislike-menu .menu-item:hover {
    background-color: #262c33 !important;
  }

  .dislike-menu .menu-text {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }

  .dislike-menu .menu-item .menu-icon path {
    fill: #9aa6b0 !important;
  }

  /* Below 960px the menu rows and the tag block gain 1px #e5e6eb `::after`
     separators — pseudo-element backgrounds, so no border reset reaches them. */
  .dislike-menu .menu-item::after,
  .dislike-menu .tags-row::after {
    background: #2d333b !important;
  }

  /* Surfaces juejin's stylesheet paints a hardcoded #fff that we could NOT reach
     logged-out on any page type (they need an account, a live campaign, or a paged
     result set), enumerated straight out of `app.css` / `10.css` rather than left to
     ship white: the byte-design pagination strip, the generic `.dropdown-menu`, the
     aside promo panel, the `secondary` button, the footer WeChat QR flyout, and the
     activity nav tooltip (white panel + #17181a text + a white ::before-less
     `.triangle` span). Unverified against a live element — see the review notes. */
  ul .byte-pagination__item,
  .byte-pagination__item,
  .dropdown-menu,
  .aside-top-section,
  .qr-panel,
  .nav-item.activities .tip {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  ul .byte-pagination__item--active,
  ul .byte-pagination__item:hover,
  .byte-pagination__item--active {
    background-color: #1a2433 !important;
    color: #5fb0e6 !important;
  }

  .nav-item.activities .tip .triangle {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  .ui-btn.secondary {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
  }

  /* byte-design floating surfaces hardcode DARK text (#1d252f / #282f38) on the
     white `--juejin-popup` panel. `.byte-popover` already read dark-on-dark; the
     modal and light tooltip only turn dark-on-dark once the token above darkens
     them, so their text MUST be lifted in the same pass. */
  .byte-popover,
  .byte-tooltip--light {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  .byte-popover__content {
    color: #c4cdd6 !important;
  }

  .byte-modal__content {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }

  /* The profile "…" overflow menu is another white display:none panel. */
  .more-panel {
    background-color: #1c2128 !important;
  }

  .more-panel,
  .more-panel .more-item {
    color: #c4cdd6 !important;
  }

  /* Their pointer arrows are PSEUDO-element triangles, so the `*` border reset
     above never reached them and they keep the site's white fill — invisible while
     the panel was white, a bright spike once we darken it. `.more-panel` draws a
     two-layer arrow (::before = outline, ::after = fill). */
  .share-popup::after {
    border-right-color: #1c2128 !important;
  }

  .more-panel::before {
    border-bottom-color: #262c33 !important;
  }

  .more-panel::after {
    border-bottom-color: #1c2128 !important;
  }

  /* 1px `.split` separators inside those panels hardcode #e4e6eb; the course
     author link draws its separator as a light 1px `::after` right border. */
  .split {
    background-color: #262c33 !important;
  }

  .jj-link.items.author::after {
    border-right-color: #262c33 !important;
  }

  /* ---------- Misc surfaces / overlays ---------- */
  .byte-tooltip__content,
  .byte-popconfirm,
  .tooltip,
  .popper,
  .v-popper__inner {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* Floating action dock (bottom-right): customer-service chat `.meiqia-btn`, the
     "..." more button and the scroll-triggered back-to-top `.to-top-btn` are all
     `.btn.btn-hover` circles with a hardcoded white bg. The to-top button only
     mounts after scrolling (audit-blind at top-of-page), the others glare white on
     the dark page. Dark to the elevated surface; their blue/grey glyphs still read. */
  .btn.btn-hover,
  .btn.btn-hover.meiqia-btn,
  .btn.btn-hover.to-top-btn {
    background-color: #1c2128 !important;
    border: 1px solid #262c33 !important;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.4) !important;
  }

  /* Article pages float an "AI 助手" vertical pill (`.btn.btn-ai`) against the right
     margin with a hardcoded white fill — a bright capsule on the dark page. */
  .btn.btn-ai {
    background-color: #1c2128 !important;
    border: 1px solid #262c33 !important;
    color: #c4cdd6 !important;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.4) !important;
  }

  /* Its "AI 助手" caption is an `::after` with `content:` and its OWN hardcoded
     #0c0d0e — pseudo text, so no `color` walk sees it and the element rule above
     cannot reach it. Darkening the pill alone left the caption near-black, 1.2:1. */
  .btn.btn-ai::after {
    color: #c4cdd6 !important;
  }

  /* Article-page left action rail (like/comment/collect/share/report/fullscreen +
     author avatar) are `.panel-btn` circles with a hardcoded white bg — at 48px
     they slip under the audit size filter and glare as bright discs down the left
     margin. Dark to the elevated surface; their #9aa6b0 glyphs still read, and the
     active like/collect accents are preserved by the semantic rules above. */
  .panel-btn,
  .panel-btn.author,
  .panel-btn.with-badge,
  .share-btn.panel-btn {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
  }

  /* Skeleton / placeholder shimmer blocks. Juejin's loader is `.xitu-skeleton`
     (white card) whose `.xitu-skeleton-line` bars shimmer via a LIGHT bg-image
     gradient (bg-color transparent) — dark the card and remap the gradient so
     loading states don't flash white. */
  .skeleton,
  .skeleton-item,
  .loading-block,
  .xitu-skeleton {
    background-color: #1c2128 !important;
  }

  .xitu-skeleton-line {
    background-image: linear-gradient(90deg, #21262d 25%, #2d333b 37%, #21262d 63%) !important;
  }

  /* Empty-state placeholder boxes */
  .common-empty,
  .empty-box,
  .empty-block,
  .no-data {
    background-color: transparent !important;
    color: #8b949e !important;
  }

  /* Footer */
  .main-footer,
  footer {
    background-color: #0d1117 !important;
    color: #8b949e !important;
    border-top: 1px solid #262c33 !important;
  }

  .main-footer a,
  footer a {
    color: #8b949e !important;
  }
}
